import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["input__shape"])
    dtype = getattr(torch, ctx["input__dtype"])
    inp = torch.randn(shape, dtype=dtype, device=device) * 10
    return {"input": inp}


def run_correctness(input):
    return torch.fix(input.float()).to(input.dtype)


def run(input):
    return torch.fix(input)
